css:
@media print {
  body { background:#fff; }
  .topbar, .toc { display:none; }
  .shell { display:block; max-width:none; padding:0; }
  .page { box-shadow:none; border-radius:0; padding:0 6mm; }
  .qcard, .callout, .figcard, .fcard { break-inside:avoid; }
  .sechead, .yearhead { break-after:avoid; }
}
